USES_OLD_COLUMN = {1: True, 2: True, 3: False}

def can_contract(unbackfilled, fleet_versions):
    reasons = []
    if unbackfilled:
        reasons.append(f"{unbackfilled} rows not backfilled")
    old = sorted({v for v in fleet_versions if USES_OLD_COLUMN[v]})
    if old:
        reasons.append(f"instances on v{', v'.join(map(str, old))} still use members.name")
    return not reasons, reasons

print(can_contract(0, [3, 3, 2, 2]))
